import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    float* __restrict__ out,
    int N, int Cin, int H, int W,
    int Cout, int KH, int KW,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW,
    int Hout, int Wout)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    long total = (long)N * Cout * Hout * Wout;
    if (idx >= total) return;

    int wo = idx % Wout;
    int tmp = idx / Wout;
    int ho = tmp % Hout;
    tmp /= Hout;
    int co = tmp % Cout;
    int n = tmp / Cout;

    float sum = 0.0f;

    for (int ci = 0; ci < Cin; ci++) {
        const float* x_ptr = x + ((long)(n * Cin + ci)) * H * W;
        const float* w_ptr = w + ((long)(co * Cin + ci)) * KH * KW;

        for (int kh = 0; kh < KH; kh++) {
            int h_in = ho * strideH - padH + kh * dilH;
            if (h_in < 0 || h_in >= H) continue;
            const float* x_row = x_ptr + h_in * W;
            const float* w_row = w_ptr + kh * KW;

            for (int kw = 0; kw < KW; kw++) {
                int w_in = wo * strideW - padW + kw * dilW;
                if (w_in < 0 || w_in >= W) continue;
                sum += x_row[w_in] * w_row[kw];
            }
        }
    }

    out[idx] = sum;
}

torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW)
{
    x = x.contiguous();
    weight = weight.contiguous();

    int N = x.size(0);
    int Cin = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    int Cout = weight.size(0);
    int KH = weight.size(2);
    int KW = weight.size(3);

    int Hout = (H + 2 * padH - dilH * (KH - 1) - 1) / strideH + 1;
    int Wout = (W + 2 * padW - dilW * (KW - 1) - 1) / strideW + 1;

    auto out = torch::zeros({N, Cout, Hout, Wout}, x.options());

    long total = (long)N * Cout * Hout * Wout;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    conv2d_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        N, Cin, H, W,
        Cout, KH, KW,
        strideH, strideW,
        padH, padW,
        dilH, dilW,
        Hout, Wout
    );

    return out;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for 2D convolution
    with square input and asymmetric kernel, dilation, and padding.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.use_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1])
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

        self.conv2d_cuda = conv2d_module.conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda()
        weight = self.weight.cuda()

        out = self.conv2d_cuda(
            x, weight,
            self.stride, self.stride,
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1]
        )

        if self.bias is not None:
            out = out + self.bias.view(1, -1, 1, 1)

        return out


batch_size = 8
in_channels = 32
out_channels = 64
kernel_size = (5, 9)
width = 512
height = 512
stride = 1
padding = (2, 4)
dilation = (2, 3)


def get_inputs():
    x = torch.rand(batch_size, in_channels, height, width)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size, stride, padding, dilation]

